import { readFileSync } from 'node:fs'
import { defineConfig } from 'vitepress'
import { siteBase } from '../scripts/base.ts'
import type { PackageInfo } from '../scripts/packages.ts'
import { searchExcerpt } from '../scripts/searchExcerpt.ts'
import { buildSidebar, type SidebarItem } from '../scripts/sidebar.ts'

const base = siteBase()
const repo = 'https://github.com/streaming-video-technology-alliance/common-media-library'

// Generated by `node scripts/prepare.ts` and `typedoc`. Read at config time, not imported,
// so `tsc` does not need the generated files.
const packages: PackageInfo[] = JSON.parse(
	readFileSync(new URL('../packages/packages.json', import.meta.url), 'utf8'),
)
const apiSidebar: SidebarItem[] = JSON.parse(
	readFileSync(new URL('../api/typedoc-sidebar.json', import.meta.url), 'utf8'),
)
const sidebar = buildSidebar(packages, apiSidebar)

export default defineConfig({
	title: 'Common Media Library',
	description:
		'TypeScript libraries for web video players, maintained by the Streaming Video Technology Alliance.',
	base,
	cleanUrls: true,
	outDir: 'dist',
	srcExclude: ['**/node_modules/**'],
	head: [
		['link', { rel: 'icon', type: 'image/svg+xml', href: `${base}cml-mark.svg` }],
		['link', { rel: 'icon', type: 'image/png', sizes: '64x64', href: `${base}favicon.png` }],
		['link', { rel: 'apple-touch-icon', href: `${base}apple-touch-icon.png` }],
	],
	themeConfig: {
		logo: {
			light: '/cml-lockup-light.svg',
			dark: '/cml-lockup-dark.svg',
			alt: 'Common Media Library',
		},
		siteTitle: false,
		nav: [
			{ text: 'Guide', link: '/guide/getting-started' },
			{ text: 'Packages', link: '/packages/', activeMatch: '^/(packages|api)/' },
			{ text: 'Releases', link: '/releases/' },
			{ text: 'LLMs', link: `${base}llms.txt`, target: '_self' },
		],
		sidebar,
		socialLinks: [
			{ icon: 'github', link: repo },
			{ icon: 'discord', link: 'https://discord.gg/g2c5vwGvUc' },
		],
		footer: {
			message: 'A Streaming Video Technology Alliance project.',
			copyright: 'Released under the Apache-2.0 license.',
		},
		search: {
			provider: 'local',
			options: {
				async _render(src, env, md) {
					if (env.relativePath.startsWith('api/')) {
						return md.renderAsync(searchExcerpt(src))
					}

					const html = await md.renderAsync(src, env)
					return env.frontmatter?.['search'] === false ? '' : html
				},
			},
		},
	},
})
